INSERT INTO kotoba (id, kanji, hiragana, meaning_id, meaning_en, notes, example_sentence, example_translation, level) VALUES
(101, '圧倒', 'あっとう', 'menguasai sepenuhnya ; mengalahkan telak', 'overwhelm; overpower', '※ Ungkapan kekuatan atau keunggulan yang jauh melampaui lawan.', '相手チームを圧倒的な強さで破った。', 'Mengalahkan tim lawan dengan keunggulan yang mutlak.', 'N2'),
(102, '著しい', 'いちじるしい', 'sangat mencolok ; signifikan', 'remarkable; striking', '※ Perubahan atau kemajuan yang sangat terlihat jelas oleh mata.', '近年、技術の進歩は著しい。', 'Dalam beberapa tahun terakhir, kemajuan teknologi sangat pesat dan mencolok.', 'N2'),
(103, '紛らわしい', 'まぎらわしい', 'membingungkan ; rancu (mirip sehingga susah dibedakan)', 'confusing; misleading', '※ Dua hal yang begitu mirip sehingga rawan membuat salah sangka.', 'よく似た名前で紛らわしい。', 'Namanya sangat mirip sehingga membingungkan.', 'N2'),
(104, '相違', 'そうい', 'perbedaan ; ketidakcocokan fakta', 'difference; discrepancy', '※ Perbedaan resmi/formal antara data atau kesaksian.', '双方の主張に大きな相違がある。', 'Terdapat perbedaan besar dalam klaim kedua belah pihak.', 'N2'),
(105, '是正', 'ぜせい', 'koreksi ; pelurusan (keadaan buruk menjadi benar)', 'correction; rectification', '※ Memperbaiki ketimpangan, ketidakadilan, atau kesalahan sistemik.', '格差を是正するための措置を講じる。', 'Mengambil langkah-langkah untuk meluruskan kesenjangan.', 'N2'),
(106, '妥協', 'だきょう', 'kompromi ; jalan tengah', 'compromise; concession', '※ Mengalah sedikit demi mencapai kesepakatan bersama.', '双方が歩み寄って妥協した。', 'Kedua pihak saling mendekat dan mencapai kompromi.', 'N2'),
(107, '模索', 'もさく', 'mencari-cari jalan keluar ; meraba-raba solusi', 'groping; searching for a way', '※ Berusaha keras menemukan solusi dalam kegelapan/ketidakpastian.', '新しいビジネスモデルを模索している。', 'Sedang mencari-cari model bisnis baru.', 'N2'),
(108, '享受', 'きょうじゅ', 'menikmati ; menerima anugerah/manfaat', 'enjoyment; reception', '※ Menerima dan menikmati keuntungan, hak, atau alam bebas.', '平和の恩恵を十分に享受する。', 'Menikmati sepenuhnya berkah dari perdamaian.', 'N2'),
(109, '遮断', 'しゃだん', 'pemutusan ; isolasi ; pemblokiran', 'interception; isolation', '※ Memutus aliran listrik, informasi, atau lalu lintas.', '緊急時に交通を遮断する。', 'Memutus arus lalu lintas pada saat darurat.', 'N2'),
(110, '崩壊', 'ほうかい', 'runtuh ; ambruknya sistem/bangunan', 'collapse; breakdown', '※ Runtuhnya tatanan, ekonomi, atau struktur fisik.', 'バブル経済の崩壊が始まった。', 'Runtuhnya ekonomi gelembung telah dimulai.', 'N2'),
(111, '蓄積', 'ちくせき', 'akumulasi ; penimbunan ; penumpukan', 'accumulation; store', '※ Menumpuknya kelelahan, modal, atau pengalaman dari waktu ke waktu.', '日頃の疲労が蓄積している。', 'Rasa lelah sehari-hari telah menumpuk.', 'N2'),
(112, '促進', 'そくしん', 'akselerasi ; mendorong percepatan', 'promotion; acceleration', '※ Mempercepat kemajuan proyek, metabolisme, atau perdagangan.', '両国の経済交流を促進する。', 'Mendorong percepatan pertukaran ekonomi kedua negara.', 'N2'),
(113, '抑制', 'よくせい', 'penekanan ; pengendalian diri ; meredam', 'control; suppression', '※ Menahan emosi, inflasi, atau pertumbuhan bakteri.', '感情を抑制して冷静に話す。', 'Meredam emosi dan berbicara dengan tenang.', 'N2'),
(114, '緩和', 'かんわ', 'pelonggaran ; peredaan ketegangan', 'relaxation; relief', '※ Meringankan regulasi, rasa sakit, atau ketegangan politik.', '痛みを緩和する薬を飲む。', 'Meminum obat untuk meredakan rasa sakit.', 'N2'),
(115, '把握', 'はあく', 'pemahaman mendalam ; menggenggam situasi', 'grasp; comprehension', '※ Memahami kondisi atau inti masalah dengan jelas dan akurat.', '現状を正確に把握することが重要だ。', 'Sangat penting untuk memahami situasi saat ini dengan tepat.', 'N2'),
(116, '該当', 'がいとう', 'relevan ; memenuhi syarat kriteria', 'corresponding to; falling under', '※ Cocok dengan pasal, syarat, atau kondisi tertentu.', '条件に該当する方のみ応募できます。', 'Hanya mereka yang memenuhi kriteria yang dapat mendaftar.', 'N2'),
(117, '妥当', 'だとう', 'wajar ; tepat ; masuk akal', 'proper; reasonable', '※ Keputusan atau kesimpulan yang pantas dan dapat diterima akal sehat.', 'その判断は妥当だと言える。', 'Keputusan itu dapat dikatakan sangat wajar dan tepat.', 'N2'),
(118, '抜擢', 'ばってき', 'promosi khusus ; pengangkatan luar biasa', 'selection; promotion', '※ Memilih seseorang yang berprestasi melompati urutan senioritas.', '若手社員が大役へ大抜擢された。', 'Karyawan muda dipromosikan secara istimewa memegang peran besar.', 'N2'),
(119, '克服', 'こくふく', 'menaklukkan ; mengatasi rintangan', 'conquest; overcoming', '※ Menang atas kelemahan diri, trauma, atau penyakit.', '弱点を克服して勝利をつかんだ。', 'Mengatasi kelemahan diri dan meraih kemenangan.', 'N2'),
(120, '兆候', 'ちょうこう', 'tanda-tanda awal ; gelagat', 'sign; symptom', '※ Gejala awal sebelum peristiwa besar atau penyakit terjadi.', '景気回復の兆候が見られる。', 'Tanda-tanda pemulihan ekonomi mulai tampak.', 'N2'),
(121, '破綻', 'はたん', 'bangkrut ; hancur berantakan', 'failure; bankruptcy', '※ Runtuhnya keuangan atau gagalnya rencana secara telak.', '財政が破綻の危機に瀕している。', 'Kondisi finansial berada di ambang kebangkrutan.', 'N2'),
(122, '概ね', 'おおむね', 'pada umumnya ; garis besarnya', 'generally; mostly', '※ Sebagian besar atau secara garis umum sudah sesuai rencana.', '計画は概ね順調に進んでいる。', 'Rencana secara garis besar berjalan lancar.', 'N2'),
(123, '予め', 'あらかじめ', 'sebelumnya ; di awal waktu', 'beforehand; in advance', '※ Melakukan persiapan atau pemberitahuan sebelum peristiwa terjadi.', '費用を予め計算しておく。', 'Menghitung biayanya terlebih dahulu di awal.', 'N2'),
(124, '専ら', 'もっぱら', 'semata-mata ; melulu fokus pada', 'entirely; solely', '※ Hampir seluruh waktu atau energinya dialokasikan hanya untuk hal itu.', '休日は専ら読書をして過ごす。', 'Hari libur semata-mata kuhabiskan untuk membaca buku.', 'N2'),
(125, '果たして', 'はたして', 'apakah benar-benar (keraguan / pembuktian)', 'really; as expected', '※ Sering dipakai dalam kalimat tanya keraguan atau kesesuaian prediksi.', '彼の言ったことは果たして本当だろうか。', 'Apakah hal yang dia katakan benar-benar nyata?', 'N2');
INSERT INTO kotoba (id, kanji, hiragana, meaning_id, meaning_en, notes, example_sentence, example_translation, level) VALUES
(151, '凌駕', 'りょうが', 'mengungguli jauh ; melampaui kehebatan', 'surpassing; outstripping', '※ Prestasi atau kemampuan yang jauh melewati standar orang lain.', '彼の才能は前任者を遥かに凌駕している。', 'Bakatnya jauh mengungguli pendahulunya.', 'N1'),
(152, '委ねる', 'ゆだねる', 'mempercayakan penuh wewenang ; menyerahkan', 'to entrust; abandon to', '※ Menyerahkan nasib atau keputusan akhir kepada orang lain.', '判断をすべて専門家に委ねる。', 'Menyerahkan seluruh keputusan kepada sang pakar.', 'N1'),
(153, '醸し出す', 'かもしだす', 'memancarkan suasana ; menciptakan aura', 'to create (an atmosphere); exude', '※ Memancarkan kesan atau atmosfer khas tertentu secara alami.', '独特の落ち着いた雰囲気を醸し出している。', 'Memancarkan suasana tenang yang sangat khas.', 'N1'),
(154, '汲み取る', 'くみとる', 'memahami maksud tersirat ; berempati', 'to understand; surmise', '※ Menangkap perasaan atau konteks tanpa perlu diucapkan terang-terangan.', '相手の意図を正確に汲み取る。', 'Memahami maksud tersirat lawan bicara dengan tepat.', 'N1'),
(155, '怠惰', 'たいだ', 'kemalasan ; bermalas-malasan', 'laziness; sloth', '※ Sifat malas yang membiarkan kewajiban terbengkalai.', '怠惰な生活態度を厳しく戒める。', 'Memperingatkan dengan tegas sikap hidup yang malas.', 'N1'),
(156, '欠如', 'けつじょ', 'ketiadaan ; defisit ; kurangnya suatu hal', 'lack; absence', '※ Hilangnya moral, rasa tanggung jawab, atau kesadaran.', '危機管理意識の欠如が事故を招いた。', 'Ketiadaan kesadaran manajemen risiko telah memicu kecelakaan.', 'N1'),
(157, '喚起', 'かんき', 'membangkitkan ; menggugah perhatian', 'arousing; awakening', '※ Menggugah kesadaran masyarakat atau rasa simpati.', '世論の注意を喚起する。', 'Menggugah perhatian dari opini publik luas.', 'N1'),
(158, '措置', 'そち', 'tindakan penanganan ; langkah darurat', 'measure; step', '※ Keputusan kebijakan resmi untuk menanggulangi situasi krisis.', '緊急安全措置を速やかに発令した。', 'Segera memberlakukan tindakan pengamanan darurat.', 'N1'),
(159, '戒める', 'いましめる', 'memperingatkan keras ; menasihati agar waspada', 'to warn; admonish', '※ Menegur atau mengingatkan diri sendiri agar tidak lengah.', '油断しないよう自らを戒める。', 'Mengingatkan diri sendiri agar tidak lengah sedikit pun.', 'N1'),
(160, '覆す', 'くつがえす', 'menjungkirbalikkan ; membalikkan keadaan', 'to overturn; upset', '※ Membalikkan vonis pengadilan, teori lama, atau dugaan.', '常識を覆す大発見がなされた。', 'Telah ditemukan penemuan besar yang menjungkirbalikkan akal sehat.', 'N1'),
(161, '阻む', 'はばむ', 'merintangi ; menghalangi laju jalan', 'to obstruct; prevent', '※ Menghambat kemajuan atau laju seseorang.', '行く手を阻む巨大な岩壁。', 'Dinding batu raksasa yang merintangi arah perjalanan.', 'N1'),
(162, '促す', 'うながす', 'mendorong agar bertindak ; mendesak', 'to urge; prompt', '※ Meminta atau memotivasi orang lain untuk segera mengambil langkah.', '注意を促す看板を設置する。', 'Memasang papan peringatan untuk mendorong kehati-hatian.', 'N1'),
(163, '免れる', 'まぬかれる', 'luput dari ; lolos dari marabahaya', 'to escape; avoid', '※ Selamat dari hukuman, bencana, atau jeratan maut.', '奇跡的に一命を免れた。', 'Secara ajaib berhasil luput dari kematian.', 'N1'),
(164, '巧み', 'たくみ', 'lihai ; terampil penuh kecerdikan', 'skillful; clever', '※ Keterampilan teknik atau kepandaian berbicara yang sangat halus.', '巧みな言葉遣いで相手を説得する。', 'Meyakinkan lawan bicara dengan pilihan kata yang lihai.', 'N1'),
(165, '厳粛', 'げんしゅく', 'khidmat ; hening penuh kesakralan', 'solemn; grave', '※ Suasana upacara yang sakral dan membuat orang tertunduk hormat.', '厳粛な雰囲気の中で式典が執り行われた。', 'Upacara diselenggarakan dalam suasana yang khidmat.', 'N1');
